  1→package cli
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"io"
  8→	"net/url"
  9→	"os/exec"
 10→	"runtime"
 11→	"time"
 12→
 13→	apiurl "github.com/entireio/cli/cmd/entire/cli/api"
 14→	"github.com/entireio/cli/cmd/entire/cli/auth"
 15→	"github.com/spf13/cobra"
 16→)
 17→
 18→const fallbackDeviceAuthPollInterval = time.Second
 19→const slowDownBackoff = 5 * time.Second
 20→const maxPollInterval = 30 * time.Second
 21→const maxExpiresIn = 15 * time.Minute
 22→const maxTransientErrors = 5
 23→
 24→// browserOpenFunc is the signature for opening a URL in the user's browser.
 25→type browserOpenFunc func(ctx context.Context, url string) error
 26→
 27→// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
 28→type deviceAuthClient interface {
 29→	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
 30→	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
 31→	BaseURL() string
 32→}
 33→
 34→func newLoginCmd() *cobra.Command {
 35→	var printBrowserURL bool
 36→	var insecureHTTPAuth bool
 37→
 38→	cmd := &cobra.Command{
 39→		Use:   "login",
 40→		Short: "Log in to Entire",
 41→		RunE: func(cmd *cobra.Command, _ []string) error {
 42→			client := auth.NewClient(nil)
 43→
 44→			if !insecureHTTPAuth {
 45→				if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
 46→					return fmt.Errorf("base URL check: %w", err)
 47→				}
 48→			}
 49→
 50→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser, printBrowserURL)
 51→		},
 52→	}
 53→
 54→	cmd.Flags().BoolVar(&printBrowserURL, "print-browser-url", false, "Print the approval URL instead of opening a browser")
 55→	cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure)")
 56→
 57→	return cmd
 58→}
 59→
 60→func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, printBrowserURL bool) error {
 61→	start, err := client.StartDeviceAuth(ctx)
 62→	if err != nil {
 63→		return fmt.Errorf("start login: %w", err)
 64→	}
 65→
 66→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 67→	approvalURL := start.VerificationURIComplete
 68→	if approvalURL == "" {
 69→		approvalURL = start.VerificationURI
 70→	}
 71→
 72→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 73→
 74→	if printBrowserURL {
 75→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 76→	} else {
 77→		if err := openURL(ctx, approvalURL); err != nil {
 78→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 79→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 80→		} else {
 81→			fmt.Fprintln(outW, "Opened your browser for approval.")
 82→		}
 83→	}
 84→
 85→	fmt.Fprintln(outW, "Waiting for approval...")
 86→
 87→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 88→	if err != nil {
 89→		return fmt.Errorf("complete login: %w", err)
 90→	}
 91→
 92→	store := auth.NewStore()
 93→
 94→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 95→		return fmt.Errorf("save auth token: %w", err)
 96→	}
 97→
 98→	fmt.Fprintln(outW, "Login complete.")
 99→	return nil
100→}
101→
102→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
103→	expiry := time.Duration(expiresIn) * time.Second
104→	if expiry <= 0 || expiry > maxExpiresIn {
105→		expiry = maxExpiresIn
106→	}
107→	deadline := time.Now().Add(expiry)
108→	pollInterval := time.Duration(interval) * time.Second
109→	if pollInterval <= 0 {
110→		pollInterval = fallbackDeviceAuthPollInterval
111→	}
112→
113→	consecutiveErrors := 0
114→
115→	for {
116→		if time.Now().After(deadline) {
117→			return "", errors.New("device authorization expired")
118→		}
119→
120→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
121→		if err != nil {
122→			consecutiveErrors++
123→			if consecutiveErrors >= maxTransientErrors {
124→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
125→			}
126→			// Transient error — wait and retry.
127→			select {
128→			case <-ctx.Done():
129→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
130→			case <-time.After(pollInterval):
131→			}
132→			continue
133→		}
134→		consecutiveErrors = 0
135→
136→		switch result.Error {
137→		case "":
138→			if result.AccessToken == "" {
139→				return "", errors.New("device authorization completed without a token")
140→			}
141→			return result.AccessToken, nil
142→		case "authorization_pending":
143→			// no-op, will sleep and retry below
144→		case "slow_down":
145→			pollInterval += slowDownBackoff
146→			if pollInterval > maxPollInterval {
147→				pollInterval = maxPollInterval
148→			}
149→		case "access_denied":
150→			return "", errors.New("device authorization denied")
151→		case "expired_token":
152→			return "", errors.New("device authorization expired")
153→		default:
154→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
155→		}
156→
157→		select {
158→		case <-ctx.Done():
159→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
160→		case <-time.After(pollInterval):
161→		}
162→	}
163→}
164→
165→func openBrowser(ctx context.Context, browserURL string) error {
166→	u, err := url.Parse(browserURL)
167→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
168→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
169→	}
170→
171→	var command string
172→	var args []string
173→
174→	switch runtime.GOOS {
175→	case "darwin":
176→		command = "open"
177→		args = []string{browserURL}
178→	case "linux":
179→		command = "xdg-open"
180→		args = []string{browserURL}
181→	case "windows":
182→		command = "cmd"
183→		args = []string{"/c", "start", "", browserURL}
184→	default:
185→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
186→	}
187→
188→	cmd := exec.CommandContext(ctx, command, args...)
189→	if err := cmd.Start(); err != nil {
190→		return fmt.Errorf("start browser command %q: %w", command, err)
191→	}
192→
193→	if err := cmd.Process.Release(); err != nil {
194→		return fmt.Errorf("release browser process: %w", err)
195→	}
196→
197→	return nil
198→}
199→

content.text:
Good call. The `--insecure-http-auth` flag leaks a dev-only concern into the user-facing CLI. A cleaner approach: **skip the HTTPS check automatically when `ENTIRE_API_BASE_URL` is set**.

The reasoning is simple — if you've explicitly overridden the base URL, you're already in a dev/testing context. No need for a flag.

In `login.go`, replace the flag-based check:

```go
// Before
if !insecureHTTPAuth {
    if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
        return fmt.Errorf("base URL check: %w", err)
    }
}

// After
if !apiurl.IsOverridden() {
    if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
        return fmt.Errorf("base URL check: %w", err)
    }
}
```

With a simple helper in `base_url.go`:

```go
func IsOverridden() bool {
    return strings.TrimSpace(os.Getenv(BaseURLEnvVar)) != ""
}
```

Then remove the `--insecure-http-auth` flag entirely.

This keeps production users safe (always HTTPS against `entire.io`) while letting local dev "just work" without flags. Want me to implement this?

