 12→// mockClient implements deviceAuthClient for unit tests.
 13→type mockClient struct {
 14→	responses []pollResponse
 15→	calls     int
 16→}
 17→
 18→type pollResponse struct {
 19→	result *auth.DeviceAuthPoll
 20→	err    error
 21→}
