 31→func (m *mockClient) PollDeviceAuth(_ context.Context, _ string) (*auth.DeviceAuthPoll, error) {
 32→	if m.calls >= len(m.responses) {
 33→		return nil, errors.New("unexpected poll call")
 34→	}
