 40→func TestWaitForApproval_ImmediateSuccess(t *testing.T) {
 41→	t.Parallel()
 42→
 43→	poller := &mockClient{responses: []pollResponse{
 44→		{result: &auth.DeviceAuthPoll{AccessToken: "tok-123"}},
