 58→func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, printBrowserURL bool) error {
 59→	start, err := client.StartDeviceAuth(ctx)
 60→	if err != nil {
 61→		return fmt.Errorf("start login: %w", err)
 62→	}
 63→
 64→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 65→	approvalURL := start.VerificationURIComplete
 66→	if approvalURL == "" {
 67→		approvalURL = start.VerificationURI
 68→	}
 69→
 70→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 71→
 72→	if printBrowserURL {
 73→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 74→	} else {
 75→		if err := openURL(ctx, approvalURL); err != nil {
 76→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 77→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 78→		} else {
 79→			fmt.Fprintln(outW, "Opened your browser for approval.")
 80→		}
 81→	}
 82→
 83→	fmt.Fprintln(outW, "Waiting for approval...")
 84→
 85→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 86→	if err != nil {
 87→		return fmt.Errorf("complete login: %w", err)
 88→	}
 89→
 90→	store := auth.NewStore()
 91→
 92→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 93→		return fmt.Errorf("save auth token: %w", err)
 94→	}
 95→
 96→	fmt.Fprintln(outW, "Login complete.")
 97→	return nil
 98→}
