100→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
101→	expiry := time.Duration(expiresIn) * time.Second
102→	if expiry <= 0 || expiry > maxExpiresIn {
103→		expiry = maxExpiresIn
104→	}
105→	deadline := time.Now().Add(expiry)
106→	pollInterval := time.Duration(interval) * time.Second
107→	if pollInterval <= 0 {
108→		pollInterval = fallbackDeviceAuthPollInterval
109→	}
110→
111→	consecutiveErrors := 0
112→
113→	for {
114→		if time.Now().After(deadline) {
115→			return "", errors.New("device authorization expired")
116→		}
117→
118→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
119→		if err != nil {
120→			consecutiveErrors++
121→			if consecutiveErrors >= maxTransientErrors {
122→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
123→			}
124→			// Transient error — wait and retry.
125→			select {
126→			case <-ctx.Done():
127→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
128→			case <-time.After(pollInterval):
129→			}
130→			continue
131→		}
132→		consecutiveErrors = 0
133→
134→		switch result.Error {
135→		case "":
136→			if result.AccessToken == "" {
137→				return "", errors.New("device authorization completed without a token")
138→			}
139→			return result.AccessToken, nil
140→		case "authorization_pending":
141→			// no-op, will sleep and retry below
142→		case "slow_down":
143→			pollInterval += slowDownBackoff
144→			if pollInterval > maxPollInterval {
145→				pollInterval = maxPollInterval
146→			}
147→		case "access_denied":
148→			return "", errors.New("device authorization denied")
149→		case "expired_token":
150→			return "", errors.New("device authorization expired")
151→		default:
152→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
153→		}
154→
155→		select {
156→		case <-ctx.Done():
157→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
158→		case <-time.After(pollInterval):
159→		}
160→	}
161→}
