163→func openBrowser(ctx context.Context, browserURL string) error {
164→	u, err := url.Parse(browserURL)
165→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
166→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
167→	}
168→
169→	var command string
170→	var args []string
171→
172→	switch runtime.GOOS {
173→	case "darwin":
174→		command = "open"
175→		args = []string{browserURL}
176→	case "linux":
177→		command = "xdg-open"
178→		args = []string{browserURL}
179→	case "windows":
180→		command = "cmd"
181→		args = []string{"/c", "start", "", browserURL}
182→	default:
183→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
184→	}
185→
186→	cmd := exec.CommandContext(ctx, command, args...)
187→	if err := cmd.Start(); err != nil {
188→		return fmt.Errorf("start browser command %q: %w", command, err)
189→	}
190→
191→	if err := cmd.Process.Release(); err != nil {
192→		return fmt.Errorf("release browser process: %w", err)
193→	}
194→
195→	return nil
196→}
